[ApiController]
[Route("api/[controller]")]
public class OrdersController : ControllerBase
{
    [HttpGet] // GET /api/orders?page=1&size=20&status=pending
    public async Task<IActionResult> GetAll([FromQuery] int page = 1, [FromQuery] int size = 20)
        => Ok(await _svc.GetPagedAsync(page, size));

    [HttpGet("{id:int}")] // GET /api/orders/5
    public async Task<IActionResult> Get(int id)
        => await _svc.GetAsync(id) is Order o ? Ok(o) : NotFound();

    [HttpPost] // POST /api/orders
    public async Task<IActionResult> Create(OrderDto dto)
    {
        var created = await _svc.CreateAsync(dto);
        return CreatedAtAction(nameof(Get), new { id = created.Id }, created); // 201 + Location
    }

    [HttpDelete("{id:int}")] // DELETE /api/orders/5
    public async Task<IActionResult> Delete(int id)
    {
        await _svc.DeleteAsync(id);
        return NoContent(); // 204
    }
}

// Order of execution for a single request, annotated:
// 1. Request -> Kestrel
// 2. Middleware pipeline (in registration order)
// 3. Routing -> matches controller/action
// 4. Authorization filters
// 5. Resource filters (before)
// 6. Model binding + validation (ModelState)
// 7. Action filters: OnActionExecuting
// 8. Action method executes
// 9. Action filters: OnActionExecuted
// 10. Result filters (before)
// 11. Result execution -- View rendered / object serialized to JSON
// 12. Result filters (after) -> Resource filters (after)
// 13. Response travels back up the middleware pipeline
// 14. Response sent
// Exception filters wrap stages 6-11.

public class TraceFilter : ActionFilterAttribute
{
    public override void OnActionExecuting(ActionExecutingContext c) => Console.WriteLine("7: action executing");
    public override void OnActionExecuted(ActionExecutedContext c) => Console.WriteLine("9: action executed");
    public override void OnResultExecuting(ResultExecutingContext c) => Console.WriteLine("10: result executing");
    public override void OnResultExecuted(ResultExecutedContext c) => Console.WriteLine("12: result executed");
}

